# ---------- 3c. brain vessels, CSF, skull fossae, flow ----------
import shutil,json
for f in ('bodyparts3d-brain-vessels.glb.json','bodyparts3d-brain-csf.glb.json','bodyparts3d-brain-fossae.glb.json','bodyparts3d-brain-tracts.glb.json','bodyparts3d-brain-mening.glb.json','brain-flow.json'):
    shutil.copy('/home/claude/brain3d/'+f,DST+'/models/')
